import { useEffect, useMemo, useState } from 'react';
import { accountCan, friendlyServiceError, PERMISSIONS, USER_ROLES } from '../services/contracts.js';

const dateTime = value => value ? new Date(value).toLocaleString('en-ZA', { dateStyle: 'medium', timeStyle: 'short' }) : 'Not scheduled';
const dateOnly = value => value ? new Date(value).toLocaleDateString('en-ZA', { dateStyle: 'medium' }) : 'Never';
const futureInput = () => new Date(Date.now() + 86400000).toISOString().slice(0, 16);

export function ClientVisitsDashboard({ account, actions, serviceMode }) {
  const adminMode = accountCan(account, PERMISSIONS.MANAGE_LOCATION_SETTINGS);
  const managerMode = !adminMode && accountCan(account, PERMISSIONS.VIEW_VISIT_COMPLIANCE);
  const [clients, setClients] = useState([]);
  const [appointments, setAppointments] = useState([]);
  const [overview, setOverview] = useState({});
  const [compliance, setCompliance] = useState([]);
  const [locations, setLocations] = useState([]);
  const [policy, setPolicy] = useState({ defaultVisitCycleDays: 30, advanceReminderDays: 7 });
  const [query, setQuery] = useState('');
  const [selectedClient, setSelectedClient] = useState(null);
  const [scheduleStep, setScheduleStep] = useState(0);
  const [selectedAppointment, setSelectedAppointment] = useState(null);
  const [qr, setQr] = useState(null);
  const [busy, setBusy] = useState('');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');
  const [visitForm, setVisitForm] = useState({ scheduledAt: futureInput(), expectedDurationMinutes: 60, purpose: 'Monthly client relationship visit', contact: '', address: '', notes: '', agenda: '', reminder: true, followUpRequired: false });
  const [locationForm, setLocationForm] = useState({ id: '', branchId: 'cape-town', branch: 'Cape Town', address: 'Fabricated office address', latitude: '-33.9258', longitude: '18.4232', radiusMetres: '250', timeZone: 'Africa/Johannesburg', workingHours: { days: [1, 2, 3, 4, 5], start: '08:00', end: '17:00' }, active: true });

  const load = async () => {
    if (adminMode) {
      const [loadedLocations, loadedPolicy] = await Promise.all([actions.getLocations(), actions.getPolicy()]);
      setLocations(loadedLocations); setPolicy(loadedPolicy); return;
    }
    if (managerMode) {
      const [loadedCompliance, loadedAppointments] = await Promise.all([actions.getCompliance(), actions.listAppointments()]);
      setCompliance(loadedCompliance); setAppointments(loadedAppointments); return;
    }
    const [loadedClients, loadedAppointments, loadedOverview] = await Promise.all([actions.listClients(), actions.listAppointments(), actions.getOverview()]);
    setClients(loadedClients); setAppointments(loadedAppointments); setOverview(loadedOverview);
  };
  useEffect(() => { load().catch(reason => setError(friendlyServiceError(reason, 'Client visit information could not be loaded.'))); }, [account.role]);

  const run = async (key, operation, success) => {
    setBusy(key); setError(''); setMessage('');
    try { const result = await operation(); setMessage(success); await load(); return result; }
    catch (reason) { setError(friendlyServiceError(reason, 'The client-visit action could not be completed.')); return null; }
    finally { setBusy(''); }
  };
  const filteredClients = useMemo(() => clients.filter(client => !query.trim() || `${client.company} ${client.primaryContact} ${client.branchId}`.toLowerCase().includes(query.toLowerCase())), [clients, query]);

  if (adminMode) return <AdminLocations locations={locations} policy={policy} setPolicy={setPolicy} form={locationForm} setForm={setLocationForm} busy={busy} run={run} actions={actions} />;
  if (managerMode) return <ManagerCompliance compliance={compliance} appointments={appointments} busy={busy} run={run} actions={actions} />;

  const schedule = async event => {
    event.preventDefault();
    const result = await run('schedule', () => actions.schedule(selectedClient.id, visitForm), 'Client visit scheduled and audited.');
    if (result) setSelectedClient(null);
  };
  const openSchedule = client => { setScheduleStep(0); setSelectedClient(client); setVisitForm(current => ({ ...current, scheduledAt: futureInput(), contact: client.primaryContact, address: client.address })); };
  const active = appointments.filter(item => ['scheduled', 'in_progress'].includes(item.status));
  const workSummaryAvailable = accountCan(account, PERMISSIONS.VIEW_OWN_WORK_LOCATION_SUMMARY);

  return <section className="app-screen operations-desktop client-visits-screen" aria-labelledby="client-visits-title">
    <header className="operations-hero visit-hero"><div><span className="eyebrow">{serviceMode === 'mock' ? 'DEMO / FABRICATED LOCATION DATA · ' : ''}Sales relationships</span><h1 id="client-visits-title">My Clients.<br /><em>Visits with evidence.</em></h1><p>Plan monthly customer visits and verify attendance without continuous background tracking.</p></div><div className="privacy-stop"><strong>Location is off by default</strong><span>Used only for a consented visit check or approved working-hours summary.</span></div></header>
    {(error || message) && <p className={`operations-message ${error ? 'is-error' : ''}`} role={error ? 'alert' : 'status'}>{error || message}</p>}
    <div className="operations-metrics visit-kpis"><Metric label="Assigned customers" value={overview.assignedCustomers} /><Metric label="Visited" value={overview.customersVisited} /><Metric label="Not visited" value={overview.customersNotVisited} /><Metric label="Scheduled" value={overview.scheduledVisits} /><Metric label="Missed" value={overview.missedVisits} /><Metric label="Due within 7 days" value={overview.dueWithin7Days} /></div>
    <section className="visit-active-panel"><div className="operations-section-title"><div><span className="eyebrow">Current month</span><h2>Appointments</h2></div><small>{active.length} active</small></div>{active.length ? active.map(item => <article key={item.id}><div><strong>{item.customer}</strong><span>{dateTime(item.scheduledAt)} · {item.purpose}</span><small>{item.verificationStatus.replaceAll('_', ' ')}</small></div><div className="visit-action-row">{item.status === 'scheduled' && <button type="button" className="secondary-button" disabled={busy} onClick={() => run(`start-${item.id}`, () => actions.start(item.id), 'Visit started. Location remains off until you request a check.')}>Start Visit</button>}{item.status === 'in_progress' && <><button type="button" className="secondary-button" disabled={busy} onClick={() => run(`geo-${item.id}`, () => actions.locationCheck(item.id, { permissionStatus: 'enabled', latitude: clients.find(client => client.id === item.clientId)?.latitude, longitude: clients.find(client => client.id === item.clientId)?.longitude }), 'Fabricated geofence check matched the customer location.')}>Demo Geofence Check</button><button type="button" className="secondary-button" disabled={busy} onClick={() => run(`confirm-${item.id}`, () => actions.customerConfirm(item.id), 'Fabricated customer confirmation recorded.')}>Customer Confirms</button><button type="button" className="secondary-button" disabled={busy} onClick={async () => { setSelectedAppointment(item); setQr(await run(`qr-${item.id}`, () => actions.createQr(item.id), 'One-time customer QR token created.')); }}>QR Confirmation</button><button type="button" className="primary-button" disabled={busy} onClick={() => run(`complete-${item.id}`, () => actions.complete(item.id, { notes: 'Fabricated completed visit.' }), 'Visit completed; verification evidence scored and audited.')}>Complete Visit</button></>}</div></article>) : <p className="operations-empty">No active appointments. Schedule one from a customer record.</p>}</section>
    <div className="visit-client-toolbar"><label><span>Search assigned customers</span><input value={query} onChange={event => setQuery(event.target.value)} placeholder="Company, contact or branch" /></label><span>{filteredClients.length} customers</span></div>
    <div className="client-health-grid">{filteredClients.map(client => <article key={client.id} className={`client-health-card is-${client.status}`}><header><span className="visit-health-dot" aria-hidden="true" /><div><strong>{client.company}</strong><small>{client.primaryContact} · {client.branchId.replaceAll('-', ' ')}</small></div><b>{client.status.toUpperCase()}</b></header><dl><div><dt>Last verified visit</dt><dd>{dateOnly(client.lastVerifiedVisitAt)}</dd></div><div><dt>Days since visit</dt><dd>{client.daysSinceLastVerifiedVisit}</dd></div><div><dt>Next planned</dt><dd>{dateOnly(client.nextPlannedVisitAt)}</dd></div><div><dt>Monthly activity</dt><dd>{client.rfqsThisMonth} RFQs · {client.quotationsThisMonth} quotes · {client.ordersThisMonth} orders</dd></div><div><dt>Open RFQs/orders</dt><dd>{client.openRfqs} RFQs · {client.openOrders} orders</dd></div><div><dt>Last interaction</dt><dd>{dateOnly(client.lastInteraction)}</dd></div></dl><button type="button" className="primary-button" onClick={() => openSchedule(client)}>Schedule Visit</button></article>)}</div>
    {workSummaryAvailable && <p className="location-precision-note">Working-location analytics are disabled in public mock mode. Production collection requires written privacy approval and is limited to configured working hours.</p>}
    {selectedClient && <div className="modal-backdrop" role="presentation"><form className="modal-card visit-schedule-modal" onSubmit={schedule}><header><div><span className="eyebrow">Schedule Visit · Step {scheduleStep + 1} of 6</span><h2>{selectedClient.company}</h2></div><button type="button" onClick={() => setSelectedClient(null)} aria-label="Close">×</button></header><div className="visit-schedule-progress"><i style={{ width: `${((scheduleStep + 1) / 6) * 100}%` }} /></div>
      {scheduleStep === 0 && <section className="visit-schedule-step"><h3>Client information</h3><dl><div><dt>Company</dt><dd>{selectedClient.company}</dd></div><div><dt>Branch</dt><dd>{selectedClient.branchId.replaceAll('-', ' ')}</dd></div></dl><FormField label="Customer contact"><input required value={visitForm.contact} onChange={event => setVisitForm({ ...visitForm, contact: event.target.value })} /></FormField><FormField label="Address"><input required value={visitForm.address} onChange={event => setVisitForm({ ...visitForm, address: event.target.value })} /></FormField></section>}
      {scheduleStep === 1 && <section className="visit-schedule-step"><h3>Visit date and time</h3><FormField label="Visit date and approximate start"><input type="datetime-local" required value={visitForm.scheduledAt} onChange={event => setVisitForm({ ...visitForm, scheduledAt: event.target.value })} /></FormField><FormField label="Expected duration (minutes)"><input type="number" min="15" max="480" required value={visitForm.expectedDurationMinutes} onChange={event => setVisitForm({ ...visitForm, expectedDurationMinutes: event.target.value })} /></FormField></section>}
      {scheduleStep === 2 && <section className="visit-schedule-step"><h3>Purpose</h3><FormField label="Visit purpose"><input required value={visitForm.purpose} onChange={event => setVisitForm({ ...visitForm, purpose: event.target.value })} /></FormField></section>}
      {scheduleStep === 3 && <section className="visit-schedule-step"><h3>Agenda and notes</h3><FormField label="Meeting agenda"><textarea value={visitForm.agenda} onChange={event => setVisitForm({ ...visitForm, agenda: event.target.value })} /></FormField><FormField label="Notes"><textarea value={visitForm.notes} onChange={event => setVisitForm({ ...visitForm, notes: event.target.value })} /></FormField></section>}
      {scheduleStep === 4 && <section className="visit-schedule-step"><h3>Reminder and follow-up</h3><label className="lab-check"><input type="checkbox" checked={visitForm.reminder} onChange={event => setVisitForm({ ...visitForm, reminder: event.target.checked })} /><span>Send in-app reminder</span></label><label className="lab-check"><input type="checkbox" checked={visitForm.followUpRequired} onChange={event => setVisitForm({ ...visitForm, followUpRequired: event.target.checked })} /><span>Follow-up required</span></label></section>}
      {scheduleStep === 5 && <section className="visit-schedule-step"><h3>Review and schedule</h3><dl><div><dt>Client</dt><dd>{selectedClient.company} · {visitForm.contact}</dd></div><div><dt>Date</dt><dd>{dateTime(visitForm.scheduledAt)}</dd></div><div><dt>Purpose</dt><dd>{visitForm.purpose}</dd></div><div><dt>Duration</dt><dd>{visitForm.expectedDurationMinutes} minutes</dd></div></dl></section>}
      <footer className="visit-schedule-actions"><button className="secondary-button" type="button" onClick={() => scheduleStep ? setScheduleStep(step => step - 1) : setSelectedClient(null)}>{scheduleStep ? 'Back' : 'Cancel'}</button>{scheduleStep < 5 ? <button className="primary-button" type="button" onClick={() => setScheduleStep(step => step + 1)}>Continue</button> : <button className="primary-button" disabled={busy} type="submit">Schedule Visit</button>}</footer></form></div>}
    {qr && selectedAppointment && <div className="modal-backdrop" role="presentation"><div className="modal-card visit-qr-card"><header><div><span className="eyebrow">Customer Visit QR</span><h2>One-time confirmation</h2></div><button type="button" onClick={() => { setQr(null); setSelectedAppointment(null); }} aria-label="Close">×</button></header><div className="mock-qr" aria-label="Fabricated QR code">▦</div><code>{qr.token}</code><p>Expires {dateTime(qr.expiresAt)}. It is tied to this customer and appointment and can be used once.</p><button type="button" className="primary-button" disabled={busy} onClick={async () => { const result = await run('verify-qr', () => actions.verifyQr(selectedAppointment.id, qr.token), 'Customer QR confirmation verified and consumed.'); if (result) { setQr(null); setSelectedAppointment(null); } }}>Scan Fabricated QR</button></div></div>}
  </section>;
}

function ManagerCompliance({ compliance, appointments, busy, run, actions }) {
  const missed = appointments.filter(item => item.status === 'missed_visit');
  return <section className="app-screen operations-desktop client-visits-screen"><header className="operations-hero visit-hero"><div><span className="eyebrow">DEMO / FABRICATED LOCATION DATA · Sales Manager</span><h1>Client Visit<br /><em>Compliance.</em></h1><p>Review monthly coverage and exceptions. Location signals are supporting evidence, never an automatic disciplinary decision.</p></div><button type="button" className="secondary-button" disabled={busy} onClick={() => run('detect-missed', () => actions.detectMissed(), 'Expired appointments checked and immutable missed-visit events recorded.')}>Check Missed Visits</button></header><div className="compliance-table"><div className="compliance-head"><span>Representative</span><span>Assigned</span><span>Visited</span><span>Scheduled</span><span>Missed</span><span>Overdue</span><span>Compliance</span></div>{compliance.map(row => <article key={row.representativeId}><span><strong>{row.representativeName}</strong><small>{row.branchId}</small></span><b>{row.assignedCustomers}</b><b>{row.customersVisited}</b><b>{row.scheduledVisits}</b><b>{row.missedVisits}</b><b>{row.customersNotVisited}</b><strong>{row.compliancePercentage}%</strong><details><summary>View visit and working-location summary</summary><p>Average {row.averageDaysBetweenVisits} days between visits · {row.averageVisitDurationMinutes} minutes average duration · {row.clientVisitHours} customer hours · {row.officeHours} office hours · {row.unclassifiedHours} unclassified hours.</p></details></article>)}</div><section className="visit-active-panel"><div className="operations-section-title"><div><span className="eyebrow">Exceptions</span><h2>Missed Client Visits</h2></div><small>{missed.length} records</small></div>{missed.length ? missed.map(item => <article key={item.id}><div><strong>{item.customer}</strong><span>{dateTime(item.scheduledAt)} · {item.purpose}</span><small>{item.missedReason || 'Representative reason pending'}</small></div></article>) : <p className="operations-empty">No missed appointments in the current fabricated dataset.</p>}</section></section>;
}

function AdminLocations({ locations, policy, setPolicy, form, setForm, busy, run, actions }) {
  return <section className="app-screen operations-desktop client-visits-screen"><header className="operations-hero visit-hero"><div><span className="eyebrow">Administrator · System Settings · Locations</span><h1>Office locations.<br /><em>Privacy by design.</em></h1><p>Configure fabricated geofences and working hours. Production employee tracking remains disabled pending formal approval.</p></div><div className="privacy-stop"><strong>Routine collection disabled</strong><span>No uncontrolled 24/7 tracking.</span></div></header><div className="admin-location-layout"><section><div className="operations-section-title"><div><span className="eyebrow">DEMO DATA</span><h2>Office locations</h2></div></div>{locations.map(location => <button key={location.id} type="button" className="office-location-card" onClick={() => setForm(location)}><strong>{location.branch}</strong><span>{location.address}</span><small>{location.radiusMetres} m geofence · {location.workingHours?.start}–{location.workingHours?.end} · {location.active ? 'Active' : 'Inactive'}</small></button>)}</section><form onSubmit={event => { event.preventDefault(); run('save-location', () => actions.saveLocation(form), 'Office location saved and audited.'); }}><h2>{form.id ? 'Edit location' : 'Add location'}</h2><FormField label="Branch"><select value={form.branchId} onChange={event => setForm({ ...form, branchId: event.target.value, branch: event.target.options[event.target.selectedIndex].text })}><option value="cape-town">Cape Town</option><option value="johannesburg">Johannesburg</option><option value="durban">Durban</option><option value="port-elizabeth">Port Elizabeth</option></select></FormField><FormField label="Address"><input required value={form.address} onChange={event => setForm({ ...form, address: event.target.value })} /></FormField><div className="visit-form-grid"><FormField label="Latitude"><input type="number" step="any" required value={form.latitude} onChange={event => setForm({ ...form, latitude: event.target.value })} /></FormField><FormField label="Longitude"><input type="number" step="any" required value={form.longitude} onChange={event => setForm({ ...form, longitude: event.target.value })} /></FormField><FormField label="Radius (metres)"><input type="number" min="25" required value={form.radiusMetres} onChange={event => setForm({ ...form, radiusMetres: event.target.value })} /></FormField><FormField label="Time zone"><input value={form.timeZone} onChange={event => setForm({ ...form, timeZone: event.target.value })} /></FormField></div><label className="lab-check"><input type="checkbox" checked={form.active} onChange={event => setForm({ ...form, active: event.target.checked })} /><span>Location active</span></label><button className="primary-button" disabled={busy}>Save Location</button></form></div><section className="visit-policy-card"><h2>Visit and retention policy</h2><div className="visit-form-grid"><FormField label="Default visit cycle days"><input type="number" min="7" value={policy.defaultVisitCycleDays} onChange={event => setPolicy({ ...policy, defaultVisitCycleDays: event.target.value })} /></FormField><FormField label="Advance reminder days"><input type="number" min="1" value={policy.advanceReminderDays} onChange={event => setPolicy({ ...policy, advanceReminderDays: event.target.value })} /></FormField></div><p>Routine working-location analytics: <strong>Disabled</strong>. Location-event retention: {policy.locationEventRetentionDays} days.</p><button type="button" className="secondary-button" disabled={busy} onClick={() => run('policy', () => actions.savePolicy(policy), 'Visit policy confirmed and audited.')}>Save Safe Demo Policy</button></section></section>;
}

function Metric({ label, value }) { return <article><strong>{value ?? 0}</strong><span>{label}</span></article>; }
function FormField({ label, children }) { return <label className="form-field"><span>{label}</span>{children}</label>; }
